+++ b/src/hb-raster-draw.cc
@@ -1259,15 +1259,17 @@ cell_add (int32_t *area, int16_t *cover, unsigned width, int col,
       int32_t dy = fy1 - fy0;
       cover[0] += (int16_t) (dy * wind);
       x_min = hb_min (x_min, 0u);
-      x_max = hb_max (x_max, 0u);
+      x_max = hb_max (x_max, 1u);
     }
+    else if (likely (col >= 0))
+      x_max = hb_max (x_max, width);
     return;
   }
   int32_t dy = fy1 - fy0;
   area[col]  += (fx0 + fx1) * dy * wind;
   cover[col] += (int16_t) (dy * wind);
   x_min = hb_min (x_min, (unsigned) col);
-  x_max = hb_max (x_max, (unsigned) col);
+  x_max = hb_max (x_max, (unsigned) col + 1);
 }

